// Prisma CLI configuration for the workflows service (Prisma 7: connection URLs live here, not in schema.prisma).
// The CLI connects as the schema-owning MIGRATOR role (sc_workflows_migrator). The running service connects
// with DATABASE_URL (runtime role sc_workflows_app) through src/database/client.ts and never sees these credentials.
import { existsSync } from 'node:fs';
import { defineConfig } from 'prisma/config';

// Local development credentials are generated by `make db-bootstrap`. CI and production inject real
// environment variables instead; process.loadEnvFile() never overrides variables that are already set.
if (existsSync('.env.migration')) process.loadEnvFile('.env.migration');

export default defineConfig({
  schema: 'prisma/schema.prisma',
  migrations: { path: 'prisma/migrations' },
  datasource: {
    // Prisma 7.10's schema engine silently does nothing when no URL is configured, so offline commands
    // (validate, generate, diff) get an unreachable placeholder instead of undefined.
    url: process.env.MIGRATION_DATABASE_URL ?? 'postgresql://offline@127.0.0.1:1/offline?schema=workflows',
    shadowDatabaseUrl: process.env.SHADOW_DATABASE_URL,
  },
});
